const trajectory = data.trajectory || {};
const candidate = data.candidate || {};
const panels = trajectory.panels || [];
const bodyQuads = trajectory.body_quads || [];
const samples = trajectory.samples || [];

root.innerHTML = `
  <div style="font:14px/1.45 system-ui,sans-serif;color:#171717">
    <div style="display:grid;grid-template-columns:minmax(280px,1.35fr) minmax(240px,.8fr);gap:18px;align-items:start">
      <div>
        <canvas id="rotor-view" width="760" height="460" style="width:100%;background:#f7f7f7;border:1px solid #dedede;border-radius:12px"></canvas>
        <div style="margin-top:7px;color:#666;font-size:12px">Winning geometry · evolved body + blade mount + blades · released from rest</div>
      </div>
      <div>
        <div style="font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#777">Physical candidate</div>
        <div style="font-size:28px;font-weight:650;margin:3px 0 12px">${Number(trajectory.descent_time_s || 0).toFixed(3)} s</div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 14px;font-size:13px">
          <div><b>${Number(trajectory.diameter_mm || 0).toFixed(1)} mm</b><br><span style="color:#777">rotor diameter</span></div>
          <div><b>${Number(trajectory.body_length_mm || 0).toFixed(1)} mm</b><br><span style="color:#777">body length</span></div>
          <div><b>${Number(trajectory.mass_g || 0).toFixed(2)} g</b><br><span style="color:#777">estimated PLA mass</span></div>
          <div><b>${Number(trajectory.max_rpm || 0).toFixed(0)} rpm</b><br><span style="color:#777">maximum autorotation</span></div>
          <div><b>${(100 * Number(trajectory.mount_height_fraction || 0)).toFixed(0)}%</b><br><span style="color:#777">blade mount height</span></div>
          <div><b>${Number(trajectory.dihedral_degrees || 0).toFixed(1)}°</b><br><span style="color:#777">blade dihedral</span></div>
        </div>
        <canvas id="rotor-chart" width="480" height="250" style="width:100%;margin-top:18px;background:#fff;border:1px solid #e5e5e5;border-radius:10px"></canvas>
        <div style="margin-top:10px;font-size:12px;color:#666">The body, blade mounting height, mass distribution and aerodynamic blade geometry all come from the same winning candidate. The STL is reconstructed from that same parameter set.</div>
      </div>
    </div>
  </div>`;

const view = root.querySelector('#rotor-view');
const ctx = view.getContext('2d');
const chart = root.querySelector('#rotor-chart');
const cctx = chart.getContext('2d');

function projectPoint(p, spin) {
  const cs = Math.cos(spin), sn = Math.sin(spin);
  const x = p[0] * cs - p[1] * sn;
  const y = p[0] * sn + p[1] * cs;
  const z = p[2];
  const yaw = -0.65, pitch = 0.95;
  const cy = Math.cos(yaw), sy = Math.sin(yaw);
  const x1 = x * cy - y * sy;
  const y1 = x * sy + y * cy;
  const cp = Math.cos(pitch), sp = Math.sin(pitch);
  const y2 = y1 * cp - z * sp;
  const z2 = y1 * sp + z * cp;
  return [x1, y2, z2];
}

function drawRotor(now) {
  const w = view.width, h = view.height;
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = '#f7f7f7'; ctx.fillRect(0, 0, w, h);
  const spin = now * 0.0017;
  const scale = Math.min(w, h) * 6.5;
  const bladePolys = panels.map(poly => ({kind:'blade', poly}));
  const bodyPolys = bodyQuads.map(poly => ({kind:'body', poly}));
  const polys = bladePolys.concat(bodyPolys).map(item => {
    const q = item.poly.map(p => projectPoint(p, spin));
    return { q, kind:item.kind, depth: q.reduce((s,p)=>s+p[2],0)/q.length };
  }).sort((a,b)=>a.depth-b.depth);

  ctx.save(); ctx.translate(w/2, h/2);
  for (const poly of polys) {
    ctx.beginPath();
    poly.q.forEach((p,i) => {
      const X = p[0] * scale, Y = -p[1] * scale;
      if (i === 0) ctx.moveTo(X,Y); else ctx.lineTo(X,Y);
    });
    ctx.closePath();
    ctx.fillStyle = poly.kind === 'body' ? '#777' : '#d9d9d9';
    ctx.fill();
    ctx.strokeStyle = poly.kind === 'body' ? '#3f3f3f' : '#333';
    ctx.lineWidth = poly.kind === 'body' ? 0.9 : 1.1;
    ctx.stroke();
  }
  ctx.restore();
  requestAnimationFrame(drawRotor);
}
requestAnimationFrame(drawRotor);

function drawChart() {
  const w=chart.width,h=chart.height,pad=34;
  cctx.clearRect(0,0,w,h); cctx.fillStyle='#fff'; cctx.fillRect(0,0,w,h);
  if (samples.length < 2) return;
  const tmax = Math.max(...samples.map(s=>s[0]), 0.001);
  const rpmmax = Math.max(...samples.map(s=>s[8]), 1);
  cctx.strokeStyle='#ddd'; cctx.lineWidth=1;
  cctx.beginPath(); cctx.moveTo(pad,12); cctx.lineTo(pad,h-pad); cctx.lineTo(w-10,h-pad); cctx.stroke();
  cctx.fillStyle='#666'; cctx.font='12px system-ui';
  cctx.fillText('RPM',7,18); cctx.fillText(`${tmax.toFixed(2)} s`,w-48,h-10);
  cctx.beginPath();
  samples.forEach((s,i)=>{
    const x=pad+(w-pad-12)*(s[0]/tmax);
    const y=h-pad-(h-pad-18)*(s[8]/rpmmax);
    if(i===0)cctx.moveTo(x,y);else cctx.lineTo(x,y);
  });
  cctx.strokeStyle='#222'; cctx.lineWidth=2; cctx.stroke();
  cctx.fillStyle='#222'; cctx.fillText(`${rpmmax.toFixed(0)} max`,pad+7,25);
}
drawChart();
